import ast,base64,hashlib,json
from pathlib import Path
ROOT=Path('/public/cyd/Person-in-WiFi-3D-repo')
payload=json.loads('{"tools/pose26_scratch/finalize.py": "", "configs/wifi/petr_wifi_tpami2026_scratch.py": "", "tools/pose26_scratch/run_experiment.py": "", "configs/wifi/smoke_scratch.py": "", "opera/models/tpami2026_scratch.py": "", "tools/pose26_scratch/verify_scratch.py": "", "tools/pose26_scratch/PLAN.md": "", "tools/pose26_scratch/manifest.json": ""}')
manifest=json.loads(base64.b64decode(payload['tools/pose26_scratch/manifest.json']))
for name in ['opera/models/tpami2026_transfer.py', 'opera/models/transfer_support.py', 'configs/wifi/petr_wifi_tpami2026_transfer.py']:
    assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==manifest['files'][name],name
for name,data in payload.items():
    target=ROOT/name
    raw=base64.b64decode(data)
    if name.endswith('.py'): ast.parse(raw.decode('utf-8'))
    if target.exists(): assert target.read_bytes()==raw, 'Refusing overwrite: '+name
for name,data in payload.items():
    target=ROOT/name
    target.parent.mkdir(parents=True,exist_ok=True)
    if not target.exists(): target.write_bytes(base64.b64decode(data))
for name,expected in manifest['files'].items():
    assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==expected,name
print(json.dumps({'uploaded':list(payload),'hashes_verified':True,'old_dependencies_unchanged':True}))
